INSERT OR IGNORE INTO lessons (id,course_id,slug,title,description,level,position,version,status) VALUES ('a1-u02-l01','course-a1-foundations','whats-this','What''s This?','Name common classroom and personal objects and identify one object with this or that.','A1',6,1,'published');
INSERT OR IGNORE INTO questions (id,lesson_id,type,prompt,options_json,answer_key,explanation,position) VALUES
('a1-u02-l01-q01','a1-u02-l01','multiple_choice','Choose the correct phrase: ___ is a pen in my hand.','[{"id":"a","text":"This"},{"id":"b","text":"These"},{"id":"c","text":"Those"}]','a','Use this for one nearby object.',1),
('a1-u02-l01-q02','a1-u02-l01','multiple_choice','Complete: It''s ___ eraser.','[{"id":"a","text":"a"},{"id":"b","text":"an"},{"id":"c","text":"the"}]','b','Eraser begins with a vowel sound, so use an.',2),
('a1-u02-l01-q03','a1-u02-l01','multiple_choice','Someone points to a book far away. Choose the question.','[{"id":"a","text":"What''s that?"},{"id":"b","text":"What are these?"},{"id":"c","text":"Who are you?"}]','a','Use that for one object at a distance.',3),
('a1-u02-l01-q04','a1-u02-l01','multiple_choice','Choose the natural answer to “What''s this?”','[{"id":"a","text":"It''s a notebook."},{"id":"b","text":"They''re notebooks."},{"id":"c","text":"I''m a notebook."}]','a','Use It''s + a/an + singular noun.',4);
INSERT OR IGNORE INTO lesson_versions (id,lesson_id,version,title,description,level,position,status,published_at) VALUES ('a1-u02-l01:v1','a1-u02-l01',1,'What''s This?','Name common classroom and personal objects and identify one object with this or that.','A1',6,'draft',NULL);
