UPDATE lesson_versions SET status='published',published_at=CURRENT_TIMESTAMP WHERE id='a1-u02-l01:v1' AND status='draft' AND (SELECT COUNT(*) FROM question_versions WHERE lesson_version_id='a1-u02-l01:v1')=4;
UPDATE lessons SET current_published_version_id='a1-u02-l01:v1' WHERE id='a1-u02-l01' AND EXISTS (SELECT 1 FROM lesson_versions WHERE id='a1-u02-l01:v1' AND status='published');

INSERT OR IGNORE INTO lessons (id,course_id,slug,title,description,level,position,version,status) VALUES ('a1-u02-l02','course-a1-foundations','things-around-you','Things Around You','Name more than one object and use basic plural forms with these and those.','A1',7,1,'published');
INSERT OR IGNORE INTO questions (id,lesson_id,type,prompt,options_json,answer_key,explanation,position) VALUES
('a1-u02-l02-q01','a1-u02-l02','multiple_choice','Choose the correct plural of “box”.','[{"id":"a","text":"boxs"},{"id":"b","text":"boxes"},{"id":"c","text":"boxies"}]','b','Add -es to many nouns ending in x.',1),
('a1-u02-l02-q02','a1-u02-l02','multiple_choice','Complete: ___ are my keys here in my hand.','[{"id":"a","text":"This"},{"id":"b","text":"That"},{"id":"c","text":"These"}]','c','Use these for more than one nearby object.',2),
('a1-u02-l02-q03','a1-u02-l02','multiple_choice','Choose the correct sentence.','[{"id":"a","text":"Those is bags."},{"id":"b","text":"Those are bags."},{"id":"c","text":"That are bags."}]','b','Those is plural, so use are.',3),
('a1-u02-l02-q04','a1-u02-l02','multiple_choice','What is the plural of “watch”?','[{"id":"a","text":"watchs"},{"id":"b","text":"watches"},{"id":"c","text":"watchies"}]','b','Add -es to nouns ending in ch.',4);
INSERT OR IGNORE INTO lesson_versions (id,lesson_id,version,title,description,level,position,status,published_at) VALUES ('a1-u02-l02:v1','a1-u02-l02',1,'Things Around You','Name more than one object and use basic plural forms with these and those.','A1',7,'draft',NULL);
