UPDATE lessons SET current_published_version_id='a1-u02-l02:v1' WHERE id='a1-u02-l02' AND EXISTS (SELECT 1 FROM lesson_versions WHERE id='a1-u02-l02:v1' AND status='published');

INSERT OR IGNORE INTO lessons (id,course_id,slug,title,description,level,position,version,status) VALUES ('a1-u02-l03','course-a1-foundations','colours-and-descriptions','Colours and Descriptions','Describe familiar objects with basic colours and size adjectives.','A1',8,1,'published');
INSERT OR IGNORE INTO questions (id,lesson_id,type,prompt,options_json,answer_key,explanation,position) VALUES
('a1-u02-l03-q01','a1-u02-l03','multiple_choice','Choose the correct phrase.','[{"id":"a","text":"a bag blue"},{"id":"b","text":"a blue bag"},{"id":"c","text":"a blues bag"}]','b','Put the adjective before the noun.',1),
('a1-u02-l03-q02','a1-u02-l03','multiple_choice','Complete: The pencils ___ green.','[{"id":"a","text":"is"},{"id":"b","text":"am"},{"id":"c","text":"are"}]','c','Use are with plural subjects.',2),
('a1-u02-l03-q03','a1-u02-l03','multiple_choice','Which word is a colour?','[{"id":"a","text":"yellow"},{"id":"b","text":"small"},{"id":"c","text":"old"}]','a','Yellow names a colour.',3),
('a1-u02-l03-q04','a1-u02-l03','multiple_choice','Choose the correct sentence.','[{"id":"a","text":"The books are reds."},{"id":"b","text":"The books are red."},{"id":"c","text":"The red are books."}]','b','Adjectives do not take plural -s.',4);
