INSERT OR IGNORE INTO lessons (id,course_id,slug,title,description,level,position,version,status) VALUES ('a1-u02-l04','course-a1-foundations','where-is-it','Where Is It?','Ask where a familiar object is and describe its position with basic prepositions.','A1',9,1,'published');
INSERT OR IGNORE INTO questions (id,lesson_id,type,prompt,options_json,answer_key,explanation,position) VALUES
('a1-u02-l04-q01','a1-u02-l04','multiple_choice','The book is ___ the desk. It is on the top surface.','[{"id":"a","text":"on"},{"id":"b","text":"under"},{"id":"c","text":"next to"}]','a','On describes contact with a surface.',1),
('a1-u02-l04-q02','a1-u02-l04','multiple_choice','Complete: Where ___ my keys?','[{"id":"a","text":"am"},{"id":"b","text":"is"},{"id":"c","text":"are"}]','c','Keys is plural, so use are.',2),
('a1-u02-l04-q03','a1-u02-l04','multiple_choice','The bag is below the chair. It is ___ the chair.','[{"id":"a","text":"in"},{"id":"b","text":"under"},{"id":"c","text":"on"}]','b','Under means below something.',3),
('a1-u02-l04-q04','a1-u02-l04','multiple_choice','Choose the correct phrase for a pen beside a notebook.','[{"id":"a","text":"next to the notebook"},{"id":"b","text":"in the notebook"},{"id":"c","text":"under to the notebook"}]','a','Next to means at the side of something.',4);
