INSERT OR IGNORE INTO lessons (id,course_id,slug,title,description,level,position,version,status) VALUES ('a1-u02-l05','course-a1-foundations','can-i-borrow','Can I Borrow That?','Ask politely to borrow an everyday object and respond to a simple request.','A1',10,1,'published');
INSERT OR IGNORE INTO questions (id,lesson_id,type,prompt,options_json,answer_key,explanation,position) VALUES
('a1-u02-l05-q01','a1-u02-l05','multiple_choice','Choose a polite request.','[{"id":"a","text":"Can I borrow your pen, please?"},{"id":"b","text":"Give pen me."},{"id":"c","text":"I borrow pen now."}]','a','Can I …? with please is a polite request.',1),
('a1-u02-l05-q02','a1-u02-l05','multiple_choice','Complete: This is ___ notebook. It belongs to you.','[{"id":"a","text":"my"},{"id":"b","text":"your"},{"id":"c","text":"his"}]','b','Use your for something belonging to the person you are speaking to.',2),
('a1-u02-l05-q03','a1-u02-l05','multiple_choice','Someone says “Thank you.” Choose a natural reply.','[{"id":"a","text":"You''re welcome."},{"id":"b","text":"Good night morning."},{"id":"c","text":"Here you are?"}]','a','You''re welcome is a common response to thanks.',3),
('a1-u02-l05-q04','a1-u02-l05','multiple_choice','Choose the best response to “Can I borrow your ruler?”','[{"id":"a","text":"Of course. Here you are."},{"id":"b","text":"I am ruler."},{"id":"c","text":"Where are you from?"}]','a','Of course. Here you are accepts the request and gives the object.',4);
INSERT OR IGNORE INTO lesson_versions (id,lesson_id,version,title,description,level,position,status,published_at) VALUES ('a1-u02-l05:v1','a1-u02-l05',1,'Can I Borrow That?','Ask politely to borrow an everyday object and respond to a simple request.','A1',10,'draft',NULL);
